ALTER TABLE works ADD COLUMN IF NOT EXISTS feature_code varchar(50);
CREATE TABLE IF NOT EXISTS features (id varchar(50) PRIMARY KEY, name varchar(100) NOT NULL, description text, category varchar(30) NOT NULL, icon varchar(50), cost integer NOT NULL DEFAULT 10, enabled boolean NOT NULL DEFAULT true, default_executor varchar(50) NOT NULL DEFAULT 'third-party', fallback_executors jsonb DEFAULT '[]'::jsonb, workflow_id varchar(50), loras jsonb DEFAULT '[]'::jsonb, default_model varchar(100), default_params jsonb DEFAULT '{}'::jsonb, sort_order integer NOT NULL DEFAULT 0, display_group varchar(50), supports_ai_assistant boolean DEFAULT false, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), updated_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id) ON DELETE SET NULL, actor_email varchar(255), actor_role varchar(20), action varchar(50) NOT NULL, resource_type varchar(50) NOT NULL, resource_id varchar(100), details jsonb DEFAULT '{}'::jsonb, ip_address varchar(45), user_agent text, created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_actor_idx ON audit_logs(actor_id, created_at);
CREATE INDEX IF NOT EXISTS audit_resource_idx ON audit_logs(resource_type, resource_id);
CREATE INDEX IF NOT EXISTS audit_action_idx ON audit_logs(action);
